package com.shatteredpixel.shatteredpixeldungeon.apd.difficulty;
import com.shatteredpixel.shatteredpixeldungeon.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero;
import com.shatteredpixel.shatteredpixeldungeon.actors.mobs.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.buffs.*;
import com.shatteredpixel.shatteredpixeldungeon.apd.HeadlessTestSupport;
import com.shatteredpixel.shatteredpixeldungeon.levels.*;
import com.shatteredpixel.shatteredpixeldungeon.sprites.CharSprite;
import com.watabou.utils.*;
import org.junit.*;
import static org.junit.Assert.*;
public class AttributedBurningIntegrationTest {
 static class Quiet extends CharSprite{@Override public void showStatus(int c,String s,Object...a){} @Override public void showStatusWithIcon(int c,String s,int i,Object...a){}}
 static class Target extends Char{Object source;Target(){HP=HT=1000;sprite=new Quiet();sprite.visible=false;alignment=Alignment.ENEMY;pos=12;}@Override public void damage(int v,Object s){source=s;super.damage(v,s);}}
 static class TestBurn extends Burning{void bind(Char c){target=c;}}
 Hero prior;Level oldLevel;int oldDepth;
 @Before public void setup()throws Exception{HeadlessTestSupport.start();prior=Dungeon.hero;oldLevel=Dungeon.level;oldDepth=Dungeon.depth;Dungeon.hero=new Hero();Dungeon.depth=4;Dungeon.level=new SewerLevel();java.lang.reflect.Method size=Level.class.getDeclaredMethod("setSize",int.class,int.class);size.setAccessible(true);size.invoke(Dungeon.level,5,5);}
 @After public void cleanup(){Dungeon.apdRestoreCustomRules(new Bundle());Dungeon.hero=prior;Dungeon.level=oldLevel;Dungeon.depth=oldDepth;}
 void rules(int p,int e,int b){Bundle a=new Bundle(),r=new Bundle();CustomDungeonRules.defaults().with(CustomDungeonRules.Slider.PLAYER_DAMAGE,p).with(CustomDungeonRules.Slider.ENEMY_DAMAGE,e).with(CustomDungeonRules.Slider.BOSS_DAMAGE,b).store(r);a.put("apd_custom_rules",r);Dungeon.apdRestoreCustomRules(a);}
 @Test public void realTickUsesPlayerEnemyBossFactorsOnceAndKeepsSource(){for(int percent=25;percent<=500;percent+=25)for(int role=0;role<3;role++){rules(role==0?percent:100,role==1?percent:100,role==2?percent:100);Char attacker=role==0?new Hero():role==1?new Rat():new Goo();Target target=new Target();TestBurn burn=new TestBurn();burn.bind(target);burn.reigniteAttributed(target,8,attacker);int raw;Random.pushGenerator(44291);try{raw=Random.NormalIntRange(1,4);}finally{Random.popGenerator();}Random.pushGenerator(44291);try{burn.act();}finally{Random.popGenerator();}assertEquals(1000-Math.round(raw*percent/100f),target.HP);assertSame(burn,target.source);}}
 @Test public void neutralFirstTickAndCachedNextDamageKeepOriginalRng(){rules(100,100,100);int first,next;long expected;Random.pushGenerator(33125);try{first=Random.NormalIntRange(1,4);next=Random.NormalIntRange(1,4);expected=Random.Long();}finally{Random.popGenerator();}Target target=new Target();TestBurn burn=new TestBurn();burn.bind(target);burn.reigniteAttributed(target,new Hero());Random.pushGenerator(33125);try{burn.act();assertEquals(expected,Random.Long());}finally{Random.popGenerator();}Bundle saved=new Bundle();burn.storeInBundle(saved);assertEquals(next,saved.getInt("next_dmg"));assertEquals(1000-first,target.HP);assertEquals(7,saved.getFloat("left"),0);}
 @Test public void sequentialDifferentCasterExtensionsRetainTheirOwnTickCause(){rules(200,300,500);Target target=new Target();TestBurn burn=new TestBurn();burn.bind(target);burn.reigniteAttributed(target,1,new Rat());burn.extendAttributed(1,new Hero());Bundle state=new Bundle();burn.storeInBundle(state);state.put("next_dmg",4);burn.restoreFromBundle(state);burn.act();assertEquals(988,target.HP);burn.storeInBundle(state);state.put("next_dmg",4);burn.restoreFromBundle(state);burn.act();assertEquals(980,target.HP);}
 @Test public void weakerReigniteDoesNotStealCauseAndLegacyReloadRemainsUnscaled(){rules(200,300,500);Target t=new Target();TestBurn burn=new TestBurn();burn.bind(t);burn.reigniteAttributed(t,8,new Goo());burn.reigniteAttributed(t,4,new Hero());Bundle saved=new Bundle();burn.storeInBundle(saved);saved.put("next_dmg",4);TestBurn copy=new TestBurn();copy.restoreFromBundle(saved);copy.bind(t);copy.act();assertEquals(980,t.HP);Bundle legacy=new Bundle();legacy.put("left",8f);legacy.put("next_dmg",4);TestBurn old=new TestBurn();old.restoreFromBundle(legacy);Target u=new Target();old.bind(u);old.act();assertEquals(996,u.HP);}
 @Test public void timedMetadataRejectsUnknownOrMismatchedValuesAndShorteningKeepsCause(){rules(200,300,500);TimedDamageOrigins o=TimedDamageOrigins.single(1,OffensiveDamageOrigin.ENEMY);o.extend(2,OffensiveDamageOrigin.PLAYER);assertEquals(12,o.scale(4));o.consume(1);assertEquals(8,o.scale(4));o.shorten(1);Bundle saved=new Bundle();o.store(saved,"x");assertEquals(8,TimedDamageOrigins.restore(saved,"x",1).scale(4));saved.put("x_version",5);try{TimedDamageOrigins.restore(saved,"x",1);fail();}catch(IllegalArgumentException expected){}assertEquals(5,saved.getInt("x_version"));assertNull(TimedDamageOrigins.restore(new Bundle(),"x",8));}
 @Test public void modifiedIncomingAverageUsesCachedRollAndFutureOwnersWithoutMutatingOrDrawingRng(){rules(200,300,500);Target t=new Target();TestBurn b=new TestBurn();b.bind(t);b.reigniteAttributed(t,1,new Rat());b.extendAttributed(1,new Hero());Bundle before=new Bundle();b.storeInBundle(before);before.put("next_dmg",4);b.restoreFromBundle(before);Random.pushGenerator(82431);long next;try{next=Random.Long();}finally{Random.popGenerator();}Random.pushGenerator(82431);try{assertEquals(17,b.totalIncomingDMG());assertEquals(next,Random.Long());}finally{Random.popGenerator();}Bundle after=new Bundle();b.storeInBundle(after);assertEquals(2,after.getFloat("left"),0);assertEquals(4,after.getInt("next_dmg"));assertArrayEquals(before.getFloatArray("apd_burn_origins_durations"),after.getFloatArray("apd_burn_origins_durations"),0);}
}
